#include <SDL.h>
#include <stdio.h>
int main(void){for(int d=2;d<=4;d+=2){SDL_Surface*s=SDL_CreateRGBSurfaceWithFormat(0,12*d,14*d,32,SDL_PIXELFORMAT_ARGB8888);SDL_Renderer*r=SDL_CreateSoftwareRenderer(s);SDL_Texture*t=SDL_CreateTexture(r,SDL_PIXELFORMAT_ARGB8888,SDL_TEXTUREACCESS_STREAMING,96,112);Uint32 b[96*112];for(int y=0;y<112;y++)for(int x=0;x<96;x++)b[y*96+x]=0xff000000u|((unsigned)x<<16)|((unsigned)y<<8);if(!r||!t||SDL_SetTextureScaleMode(t,SDL_ScaleModeNearest)||SDL_SetTextureBlendMode(t,SDL_BLENDMODE_NONE)||SDL_UpdateTexture(t,NULL,b,96*4)||SDL_RenderCopy(r,t,NULL,NULL)){fprintf(stderr,"%s\n",SDL_GetError());return 1;}SDL_RenderPresent(r);for(int y=0;y<14*d;y++)for(int x=0;x<12*d;x++){Uint32 v=((Uint32*)((Uint8*)s->pixels+y*s->pitch))[x];int sx=(2*x+1)*8/(2*d),sy=(2*y+1)*8/(2*d);if(((v>>16)&255)!=(unsigned)sx||((v>>8)&255)!=(unsigned)sy){fprintf(stderr,"mismatch d%d (%d,%d): %u,%u vs %d,%d\n",d,x,y,(v>>16)&255,(v>>8)&255,sx,sy);return 2;}}printf("PASS direct8-to-%d center-nearest, all %d sampled pixels\n",d,12*14*d*d);SDL_DestroyTexture(t);SDL_DestroyRenderer(r);SDL_FreeSurface(s);}return 0;}
